        "description": "7月25日，奇瑞集团全球累计销量正式突破2000万辆。奇瑞汽车董事长尹同跃在风云A9全球上市发布会上说：“2000万辆之后，我们不再参加内卷，我们不再只追求销量，而是要追求品牌向上，追求价值更大的创造，追求技术更多的突破，追求客户满意度更大的提升。”",
